cat "$STAMPED_JUDGE_OUTPUT/commands/response-build-02/scientific-judgment-validate.stdout"
cat "$STAMPED_JUDGE_OUTPUT/commands/response-build-02/scientific-judgment-validate.stderr"
printf '\n--- final integrity ---\n'
python - "$STAMPED_OPERATIONAL_MANIFEST" "$STAMPED_JUDGE_TARGET" <<'PY'
import hashlib,json,os,sys
m=json.load(open(sys.argv[1])); root=sys.argv[2]; changed=[];missing=[]; meta=[]; n=0
for e in m['entries']:
 rel=e['path'].removeprefix('content/workspace/')
 if rel==e['path']: continue
 n+=1; p=root if not rel else os.path.join(root,rel); kind=e['kind']
 if kind=='directory':
  if not os.path.isdir(p) or os.path.islink(p): missing.append(e['path'])
 elif kind=='symlink':
  if not os.path.islink(p): missing.append(e['path'])
  elif os.readlink(p)!=e['link_target']: changed.append((e['path'],'link'))
 elif kind=='file':
  if not os.path.isfile(p) or os.path.islink(p):
   if e['path'].startswith('content/workspace/.git/annex/keysdb/') and os.path.basename(p) in ('db','db-shm','db-wal'): meta.append({'path':e['path'],'state':'missing'})
   else: missing.append(e['path'])
   continue
  h=hashlib.sha256(open(p,'rb').read()).hexdigest()
  if e['path'].startswith('content/workspace/.git/annex/keysdb/') and os.path.basename(p) in ('db','db-shm','db-wal'):
   if h!=e['sha256']: meta.append({'path':e['path'],'state':'regular-file bytes changed'})
  elif h!=e['sha256']: changed.append((e['path'],'sha256'))
print(json.dumps({'workspace_entries':n,'nonmetadata_changed':changed,'nonmetadata_missing':missing,'annex_keydb_metadata_changes':meta},indent=2))
PY
printf '\n--- output artifact list ---\n'
find "$STAMPED_JUDGE_OUTPUT" -maxdepth 3 -type f -printf '%P\n' | sort",yield_time_ms:30000,max_output_tokens:10000}); text(r.output)

